window.RP_SESSION={"id":"S-212335fb7928","messages":[{"id":"RP-III-0173983","time":"2026-09-10T20:34:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"To. Reggiano Family \n\n레지아노들, 다들 잘 지내고 있나요? 저는 무사히 길드에 들어왔어요! 무려 어설픈 용맹이라고요? 왜, 그 있잖아요! 그 클램시요! …아무튼! 다들 걱정하시겠지만, 정말 다행히도 여긴 좋은 사람들 투성이에요. …제가 촌녀라서 그런 걸까요? 어째 같이 자란 고향 사람들보다 더 친절하네요…. 다양한 분들도 많은데, 다들 정말 착하다니까요? 만날 때마다 과일을 주는 분도 있고, 제가 겁을 먹어도 믿어주는 분들도 계세요. …그거 들으셨어요? 포투아 배 10척이 침몰했다던, 그 얘기요! 그거, 저희 길드원들이에요. 그리고, 그중에 한 명이 저고요! 좀 대단하지 않나요? 다들 걱정하신 게 부끄러우실 정도죠? 그땐 무섭고 마냥 힘들었는데, 지금 생각해 보면 절 믿어준 동료들이 마냥 고맙게만 생각이 드네요. 마음 같아선 저희 목장의 치즈라도 선물해주고 싶은데! 저랑 같이 방을 쓰시는 분이, 먹는 걸 엄청 좋아하시거든요. …사실은, 두 분께서 선물해 주신 도끼를","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0173984","time":"2026-09-10T20:35:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"……자, 이제 편지를 보낼 우편 길드를 찾아야지!\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0173985","time":"2026-09-10T20:35:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0173986","time":"2026-09-10T20:35:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]}]};
